import java.lang.reflect.*;
import java.util.*;
import java.io.*;

/**
 * Headless launcher that starts Ghidra + MCP server without requiring the
 * Ghidra Extension Manager. Uses reflection so we don't need compile-time
 * dependencies on all Ghidra JARs.
 */
public class GhidraMcpHeadless {

    static final int MCP_PORT = 8080;

    public static void main(String[] args) throws Exception {
        System.out.println("[GhidraMcpHeadless] Starting Ghidra headless with embedded MCP server...");

        // The GhidraClassLoader is already the system class loader
        // (set via -Djava.system.class.loader=ghidra.GhidraClassLoader)
        // We just need to initialize the Ghidra application framework.

        // 1. Initialize Ghidra Application
        Class<?> appClass = Class.forName("ghidra.framework.Application");
        Method initMethod = appClass.getMethod("initializeApplication");
        Object app = initMethod.invoke(null);
        System.out.println("[GhidraMcpHeadless] Ghidra Application initialized: " + app);

        // 2. Get the tool manager / create a tool
        Class<?> toolServicesClass = Class.forName("ghidra.framework.plugintool.util.ToolServices");
        Class<?> toolManagerClass = Class.forName("ghidra.framework.project.ToolManager");

        // Try to initialize headless tooling
        try {
            Class.forName("ghidra.framework.main.HeadlessGhidra");
        } catch (Exception e) {
            System.out.println("[GhidraMcpHeadless] HeadlessGhidra not available, using fallback");
        }

        // 3. Use Ghidra's tool factory to create a plugin tool
        Object tool = null;
        try {
            Class<?> toolFactory = Class.forName("ghidra.framework.plugintool.util.PluginToolFactory");
            Method createTool = toolFactory.getMethod("createTool");
            tool = createTool.invoke(null);
            System.out.println("[GhidraMcpHeadless] Tool created: " + tool.getClass().getName());
        } catch (Exception e) {
            System.out.println("[GhidraMcpHeadless] Tool factory failed: " + e.getMessage());
            // Try alternative: get from running tool
            try {
                Class<?> frontEndUtil = Class.forName("ghidra.framework.main.FrontEndUtilities");
                Method getTool = frontEndUtil.getMethod("getFrontEndTool");
                tool = getTool.invoke(null);
                System.out.println("[GhidraMcpHeadless] Got frontend tool: " + (tool != null ? tool.getClass() : "null"));
            } catch (Exception e2) {
                System.out.println("[GhidraMcpHeadless] FrontEnd tool failed: " + e2.getMessage());
            }
        }

        // 4. Load GhidraMcpPlugin via reflection and start the MCP server
        if (tool != null) {
            try {
                // Try to load the MCP server class
                Class<?> serverClass = Class.forName("com.themixednuts.GhidraMcpServer");
                Constructor<?> ctor = serverClass.getDeclaredConstructors()[0];
                ctor.setAccessible(true);

                // Need to figure out constructor params from bytecode
                // Constructor seems to take (int, int, PluginTool) or similar
                System.out.println("[GhidraMcpHeadless] GhidraMcpServer constructor params: " +
                    Arrays.toString(ctor.getParameterTypes()));

                // Try to find a no-arg or simpler constructor
                for (Constructor<?> c : serverClass.getDeclaredConstructors()) {
                    System.out.println("[GhidraMcpHeadless]   ctor(" + Arrays.toString(c.getParameterTypes()) + ")");
                }

                // Try invoke: createJettyServer is a method on the server
                try {
                    Method createJetty = serverClass.getMethod("createJettyServer", int.class);
                    Object server = serverClass.getDeclaredConstructor().newInstance();
                    Object jetty = createJetty.invoke(server, MCP_PORT);
                    System.out.println("[GhidraMcpHeadless] Jetty server created: " + jetty);

                    Method startMethod = serverClass.getMethod("start");
                    startMethod.invoke(server);
                    System.out.println("[GhidraMcpHeadless] MCP server started on port " + MCP_PORT);
                } catch (NoSuchMethodException nsme) {
                    System.out.println("[GhidraMcpHeadless] createJettyServer not found, trying alternative: " + nsme.getMessage());
                }
            } catch (Exception e) {
                System.out.println("[GhidraMcpHeadless] MCP server failed: " + e);
                e.printStackTrace();
            }
        } else {
            System.out.println("[GhidraMcpHeadless] No tool available - MCP server not started");
        }

        // 5. Keep alive
        System.out.println("[GhidraMcpHeadless] Ghidra+MCP running on port " + MCP_PORT);
        System.out.println("[GhidraMcpHeadless] Press Ctrl+C to stop");
        Thread.currentThread().join();
    }
}

